-fn top_level_description(schema: &OaSchema) -> Option<String> {
-    match schema {
-        OaSchema::Obj {
-            description: Some(description),
-            ..
-        } => Some(description.clone()),
-        OaSchema::Obj {
-            all_of: Some(all_of),
-            ..
-        } => {
-            for element in all_of {
-                if let OaSchema::Obj {
-                    description: Some(description),
-                    ..
-                } = element
-                {
-                    return Some(description.clone());
-                }
-            }
-            None
-        }
-        _ => None,
-    }
-}
